target.css:
:root {
  --ink: #203038;
  --muted: #66777b;
  --paper: #fffdf8;
  --mist: #edf3ef;
  --line: #cbd8d2;
  --teal: #227a70;
  --amber: #d78a37;
  --coral: #c95f4f;
}

* {
  box-sizing: border-box;
}

.furnace-board {
  width: 480px;
  max-width: 100%;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.board-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.title-block {
  display: grid;
  gap: 3px;
}

.eyebrow,
.subtitle,
.card-label,
.heat-note,
.station-copy small {
  margin: 0;
  color: var(--muted);
}

.eyebrow,
.card-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.1;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 21px;
  font-weight: 750;
  letter-spacing: -0.03em;
  line-height: 1;
}

.subtitle {
  font-size: 12px;
  line-height: 1.2;
}

.live {
  flex: 0 0 auto;
  padding: 6px 8px;
  color: var(--coral);
  background: var(--mist);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.kiln-layout {
  display: grid;
  grid-template-columns: 154px 1fr;
  gap: 10px;
  padding: 12px 16px;
}

.heat-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 126px;
  padding: 12px;
  background: var(--mist);
  border: 1px solid var(--line);
  border-radius: 13px;
}

.temperature {
  display: flex;
  align-items: baseline;
  gap: 3px;
}

.temperature strong {
  color: var(--coral);
  font-size: 30px;
  font-weight: 800;
  letter-spacing: -0.06em;
  line-height: 1;
}

.temperature span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.heat-scale {
  display: flex;
  gap: 4px;
}

.heat-scale span {
  flex: 1;
  height: 6px;
  border-radius: 999px;
}

.scale-cool {
  background: var(--teal);
}

.scale-warm {
  background: var(--amber);
}

.scale-hot {
  background: var(--coral);
}

.heat-note {
  font-size: 11px;
  font-weight: 600;
}

.stations {
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 7px;
}

.stations-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.stations-head h2 {
  font-size: 13px;
  font-weight: 800;
  line-height: 1;
}

.stations-head span {
  color: var(--teal);
  font-size: 11px;
  font-weight: 700;
}

.station-list {
  display: grid;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.station-row {
  display: grid;
  grid-template-columns: 25px 1fr auto;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 10px;
}

.station-mark {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  color: var(--teal);
  background: var(--mist);
  border-radius: 7px;
  font-size: 10px;
  font-weight: 800;
}

.station-copy {
  display: grid;
  gap: 1px;
  min-width: 0;
}

.station-copy strong {
  overflow: hidden;
  font-size: 12px;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.station-copy small {
  font-size: 10px;
  line-height: 1.1;
}

.state {
  padding: 4px 6px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
}

.ready {
  color: var(--teal);
  background: var(--mist);
}

.heating {
  color: var(--amber);
  background: var(--mist);
}

.hold {
  color: var(--coral);
  background: var(--mist);
}

.board-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 16px;
  background: var(--mist);
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}

.board-foot strong {
  color: var(--ink);
}

button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--teal);
  border: 0;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 750;
  line-height: 1;
}

